export function strandsForGrade(grade: number) {
  const entry = ELA_STANDARDS.find((g) => g.grade === grade);
  if (!entry) return [] as { strand: string; standards: ElaStandard[] }[];
  return ELA_STRAND_ORDER.map((strand) => ({
    strand: strand as string,
    standards: entry.standards.filter((s) => s.strand === strand),
  })).filter((group) => group.standards.length > 0);
}
